using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace FVN_REGISTER.AI.Infrastructure.Persistence;
public sealed class AiGoldenDatasetCaseRecord { public Guid Id { get; set; } public string TenantCode { get; set; } = ""; public string DatasetCode { get; set; } = ""; public string CaseType { get; set; } = ""; public string InputJson { get; set; } = "{}"; public string ExpectedJson { get; set; } = "{}"; public string? RubricJson { get; set; } public bool IsActive { get; set; } = true; public DateTimeOffset CreatedAtUtc { get; set; } }
public sealed class AiGoldenDatasetEvaluationRecord { public Guid Id { get; set; } public string TenantCode { get; set; } = ""; public Guid CaseId { get; set; } public Guid? ReleaseId { get; set; } public bool Passed { get; set; } public string? ActualJson { get; set; } public string? FailureReason { get; set; } public DateTimeOffset EvaluatedAtUtc { get; set; } }
public sealed class AiModelReleaseRecord { public Guid Id { get; set; } public string TenantCode { get; set; } = ""; public string ReleaseCode { get; set; } = ""; public string ModelProvider { get; set; } = ""; public string ModelVersion { get; set; } = ""; public string PromptVersion { get; set; } = ""; public string? SchemaCode { get; set; } public int? SchemaVersion { get; set; } public string GoldenDatasetCode { get; set; } = ""; public string Status { get; set; } = "Candidate"; public double MinimumAcceptanceRate { get; set; } = 0.95; public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset? PromotedAtUtc { get; set; } public DateTimeOffset? RetiredAtUtc { get; set; } public string CreatedBy { get; set; } = ""; }
public sealed class AiGoldenDatasetCaseConfiguration : IEntityTypeConfiguration<AiGoldenDatasetCaseRecord> { public void Configure(EntityTypeBuilder<AiGoldenDatasetCaseRecord> b) { b.ToTable("AiGoldenDatasetCases", "ai"); b.HasKey(x => x.Id); b.Property(x => x.TenantCode).HasMaxLength(64).IsRequired(); b.Property(x => x.DatasetCode).HasMaxLength(128).IsRequired(); b.Property(x => x.CaseType).HasMaxLength(64).IsRequired(); b.Property(x => x.InputJson).IsRequired(); b.Property(x => x.ExpectedJson).IsRequired(); b.Property(x => x.RubricJson); b.HasIndex(x => new { x.TenantCode, x.DatasetCode, x.IsActive }); b.HasIndex(x => new { x.TenantCode, x.Id }).IsUnique(); } }
public sealed class AiGoldenDatasetEvaluationConfiguration : IEntityTypeConfiguration<AiGoldenDatasetEvaluationRecord> { public void Configure(EntityTypeBuilder<AiGoldenDatasetEvaluationRecord> b) { b.ToTable("AiGoldenDatasetEvaluations", "ai"); b.HasKey(x => x.Id); b.Property(x => x.TenantCode).HasMaxLength(64).IsRequired(); b.Property(x => x.FailureReason).HasMaxLength(2000); b.Property(x => x.ActualJson); b.HasIndex(x => new { x.TenantCode, x.CaseId, x.EvaluatedAtUtc }); b.HasIndex(x => new { x.TenantCode, x.ReleaseId, x.EvaluatedAtUtc }); b.HasOne<AiGoldenDatasetCaseRecord>().WithMany().HasForeignKey(x => new { x.TenantCode, x.CaseId }).HasPrincipalKey(x => new { x.TenantCode, x.Id }).OnDelete(DeleteBehavior.Restrict); b.HasOne<AiModelReleaseRecord>().WithMany().HasForeignKey(x => new { x.TenantCode, x.ReleaseId }).HasPrincipalKey(x => new { x.TenantCode, x.Id }).OnDelete(DeleteBehavior.Restrict); } }
public sealed class AiModelReleaseConfiguration : IEntityTypeConfiguration<AiModelReleaseRecord> { public void Configure(EntityTypeBuilder<AiModelReleaseRecord> b) { b.ToTable("AiModelReleases", "ai"); b.HasKey(x => x.Id); b.Property(x => x.TenantCode).HasMaxLength(64).IsRequired(); b.Property(x => x.ReleaseCode).HasMaxLength(128).IsRequired(); b.Property(x => x.ModelProvider).HasMaxLength(64).IsRequired(); b.Property(x => x.ModelVersion).HasMaxLength(128).IsRequired(); b.Property(x => x.PromptVersion).HasMaxLength(128).IsRequired(); b.Property(x => x.SchemaCode).HasMaxLength(128); b.Property(x => x.GoldenDatasetCode).HasMaxLength(128).IsRequired(); b.Property(x => x.Status).HasMaxLength(16).IsRequired(); b.Property(x => x.CreatedBy).HasMaxLength(128).IsRequired(); b.HasIndex(x => new { x.TenantCode, x.ReleaseCode }).IsUnique(); b.HasIndex(x => new { x.TenantCode, x.Status }); b.HasIndex(x => new { x.TenantCode, x.Id }).IsUnique(); } }
